defmodule JoobQ.Worker.RegistrarTest do
  use ExUnit.Case, async: true

  import ExUnit.CaptureLog

  alias JoobQ.{Error, TestGateway}
  alias JoobQ.Worker.Registrar

  test "a worker registers when it starts, and again soon after a failed call" do
    bypass = Bypass.open()
    test_pid = self()
    calls = TestGateway.counter()

    TestGateway.stub(bypass, "POST", "/api/v1/sdk/workers/register", fn conn ->
      {:ok, body, conn} = Plug.Conn.read_body(conn)
      send(test_pid, {:registered, Jason.decode!(body)})
      status = if TestGateway.tick(calls) == 0, do: 503, else: 200
      Plug.Conn.resp(conn, status, ~s({"worker_id":"w-1","status":"running","ttl_ms":60000}))
    end)

    TestGateway.start_worker(bypass, except: [:register])

    assert_receive {:registered, %{"worker_id" => "w-1", "sdk_language" => "elixir"}}, 1_000
    assert_receive {:registered, %{"task_queues" => ["mail"]}}, 1_000
  end

  defp flow(name),
    do:
      name |> JoobQ.Workflow.new() |> JoobQ.Workflow.step("a", fn input, _job -> {:ok, input} end)

  defp gateway(bypass, statuses) do
    test_pid = self()
    calls = TestGateway.counter()

    TestGateway.stub(bypass, "POST", "/api/v1/sdk/blueprints", fn conn ->
      {:ok, body, conn} = Plug.Conn.read_body(conn)
      body = Jason.decode!(body)
      send(test_pid, {:blueprint, body["name"], body})
      status = Enum.at(statuses, TestGateway.tick(calls), 200)
      Plug.Conn.resp(conn, status, ~s({"error":{"code":"invalid","message":"refused here"}}))
    end)

    TestGateway.stub(bypass, "POST", "/api/v1/sdk/workers/register", fn conn ->
      send(test_pid, :registered)
      Plug.Conn.resp(conn, 503, ~s({"error":{"code":"unavailable","message":"later"}}))
    end)
  end

  test "blueprints go before the registration, are sent again after a 5xx and never after a success" do
    bypass = Bypass.open()
    gateway(bypass, [503])
    TestGateway.start_worker(bypass, workflows: [flow("shop")], except: [:register, :blueprints])

    # The first call the gateway sees is the blueprint, then the registration.
    first =
      receive do
        message -> message
      after
        1_000 -> :nothing
      end

    assert {:blueprint, "shop", body} = first

    assert %{"sdk_language" => "elixir", "worker_id" => "w-1", "blueprint" => %{"name" => "shop"}} =
             body

    assert_receive :registered, 1_000
    assert_receive {:blueprint, "shop", _again}, 2_000
    assert_receive :registered, 2_000
    refute_receive {:blueprint, _name, _body}, 1_500
  end

  test "a refused blueprint (4xx, 429 included) or one over 262144 bytes is not sent again" do
    bypass = Bypass.open()
    gateway(bypass, [422, 429])
    keys = Map.new(1..64, &{"key_#{&1}", JoobQ.Workflow.input("a_long_input_key_name_#{&1}")})
    ok = fn input, _job -> {:ok, input} end

    big =
      Enum.reduce(
        1..450,
        JoobQ.Workflow.new("big"),
        &JoobQ.Workflow.step(&2, "step_#{&1}", ok, input: keys)
      )

    TestGateway.start_worker(bypass,
      workflows: [flow("a"), flow("b"), big],
      except: [:register, :blueprints]
    )

    assert_receive {:blueprint, "a", _body}, 1_000
    assert_receive {:blueprint, "b", _body}, 1_000
    assert_receive :registered, 1_000
    assert_receive :registered, 2_000
    refute_receive {:blueprint, _name, _body}, 1_500
  end

  test "a refused blueprint's log line names JQ-902 once, after the gateway's own code" do
    answer = %{"error" => %{"code" => "invalid", "jq_code" => "JQ-822", "message" => "bad\nnode"}}

    log =
      capture_log(fn ->
        assert Registrar.sent("a", {:error, Error.from_response(422, answer)}) == :refused
      end)

    assert log =~
             "joobq: the gateway refused the blueprint of workflow a: JoobQ gateway error (422 invalid): bad node" <>
               " [JQ-822] https://joobq.io/errors/" <>
               "JQ-822 [JQ-902] https://joobq.io/errors/JQ-902"

    assert log |> String.split("JQ-902") |> length() == 3
    assert Registrar.sent("a", {:error, Error.from_response(503, answer)}) == :retry
  end

  test "a round's blueprints share one request timeout: an unanswered gateway delays the registration once" do
    bypass = Bypass.open()
    test_pid = self()

    TestGateway.stub(bypass, "POST", "/api/v1/sdk/blueprints", fn conn ->
      {:ok, body, conn} = Plug.Conn.read_body(conn)
      send(test_pid, {:blueprint, Jason.decode!(body)["name"], self()})

      receive do
        :release -> Plug.Conn.resp(conn, 503, "")
      after
        8_000 -> Plug.Conn.resp(conn, 503, "")
      end
    end)

    TestGateway.stub(bypass, "POST", "/api/v1/sdk/workers/register", fn conn ->
      send(test_pid, :registered)
      Plug.Conn.resp(conn, 200, ~s({"worker_id":"w-1","status":"running","ttl_ms":60000}))
    end)

    attach = fn event, measures, metadata, pid ->
      send(pid, {:span, event, measures, metadata})
    end

    :telemetry.attach("registrar-deadline", [:joobq, :blueprint, :stop], attach, test_pid)
    on_exit(fn -> :telemetry.detach("registrar-deadline") end)
    started = System.monotonic_time(:millisecond)

    TestGateway.start_worker(bypass,
      workflows: [flow("a"), flow("b"), flow("c")],
      lease_ttl_ms: 1_000,
      except: [:register, :blueprints]
    )

    assert_receive {:blueprint, "a", handler}, 1_000

    # A request's timeout is 5 s + a sixth of the lease: the registration follows it, b and c wait for the next round.
    assert_receive :registered, 7_000
    assert System.monotonic_time(:millisecond) - started < 6_500
    refute_received {:blueprint, "b", _pid}
    assert_receive {:span, _event, _measures, %{workflow: "a", result: :retry}}, 1_000
    send(handler, :release)
  end
